[asy]
filldraw((0, 3)--(-1, 3)--(-2, 2)--(-1, 1)--cycle,lightgrey);
filldraw((0, 3)--(1, 3)--(2, 2)--(1, 1)--cycle,lightgrey);
filldraw((0, 4)--(-1, 3)--(1, 3)--cycle,grey);
draw((-1, 1)--(0,0)--(1, 1));

filldraw((4,1)--(3,2)--(2,0)--(3,0)--cycle,lightgrey);
